/********************************************** 
 * 설명 : 최종호가수익률 조회
 ***********************************************/
scwin.fn_SearchTab1 = function() {
    if ($c.stf.getObjectValue(edt_FromDd1) == '') {
        $c.win.alert("[기준일자]를 입력하십시오.");
        edt_FromDd1.focus();
        return false;
    }
    var param = '';
    param += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_FromDd1); //기준일

    var dsNm = 'BNS_LST_ORD_YD_RCV_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectBndLstOrdYdRcvList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List1, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List1);
};


