/********************************************** 
 * 설명 : 최종호가수익률 엑셀 다운로드
 ***********************************************/
scwin.fn_DownExcel = function() {
    var file_path = "";
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    var tabIdx = tab_Main.getSelectedTabIndex();
    if (tabIdx == 1) {
        file_path = $c.session.getExcelDownPath() + "최종호가수익률_" + today + ".xlsx";
        $c.data.downloadGridViewOffice(grd_List1, "sheet1", file_path, 8, 0);
    } else if (tabIdx == 2) {
        file_path = $c.session.getExcelDownPath() + "시가평가수익률(CD_CP)_" + today + ".xlsx";
        $c.data.downloadGridViewOffice(grd_List2, "sheet1", file_path, 8, 0);
    } else if (tabIdx == 3) {
        // 시가평가수익률(채권그룹)_협회(민평4사)_20240926110126.xlsx
        file_path = $c.session.getExcelDownPath() + "시가평가수익률(채권그룹)_" + cmb_ValuInstNm3.getText() + "_" + today + ".xlsx";
        $c.data.downloadGridViewOffice(grd_List3, "sheet1", file_path, 8, 0);
    } else if (tabIdx == 4) {
        file_path = $c.session.getExcelDownPath() + "시가평가수익률(발행기관)_" + today + ".xlsx";
        $c.data.downloadGridViewOffice(grd_List4, "sheet1", file_path, 8, 0);
    } else if (tabIdx == 5) {
        file_path = $c.session.getExcelDownPath() + "원화이자스왑(IRS)_" + today + ".xlsx";
        $c.data.downloadGridViewOffice(grd_List5, "sheet1", file_path, 8, 0);
    } else if (tabIdx == 6) {
        file_path = $c.session.getExcelDownPath() + "KOFR금리_" + today + ".xlsx";
        $c.data.downloadGridViewOffice(grd_List6, "sheet1", file_path, 8, 0);
    }
};



/********************************************** 
 * 함수명   : fn_GetParListBndIsu
 * 설명       : 상장종목 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParListBndIsu = function(arrPar) {
    arrPar[0] = {
        LIST_TYPE_CD: "1" // 1 : 상장종목만, 2 : 상장폐지도 포함, else : 모두
            ,
        ISUR_NM: "",
        ISU_NM: $c.stf.getObjectValue(txb_IsuNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParListBndIsu
 * 설명       : 상장종목 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParListBndIsu = function(arrPar) {
    $c.stf.setObjectValue(txb_StdCd, arrPar[0].STD_CD);
    $c.stf.setObjectValue(txb_IsuNm, arrPar[0].ISU_NM);
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(panel_T1);
    $c.bns.BnsPanelToGroupBox(panel_T2);
    $c.bns.BnsPanelToGroupBox(panel_T3);
    $c.bns.BnsPanelToGroupBox(panel_T4);
    $c.bns.BnsPanelToGroupBox(panel_T5);
    $c.bns.BnsPanelToGroupBox(panel_T6);
    tab_Main.setSelectedTabIndex(1);

    // 현재일자 기준 직전 영업일 가져오기
    $c.market.fn_get_AgBzDd(dts_Date, $c.ut.cGetToday("yyyymmdd"));
    edt_FromDd1.setValue($c.ut.cGetToday("yyyymmdd"));

    // 시가평가수익률 세트는 기본값 : 직전영업일 
    edt_FromDd2.setValue(dts_Date.getCellData(1, "CALND_DD"));
    edt_FromDd3.setValue(dts_Date.getCellData(1, "CALND_DD"));
    edt_FromDd4.setValue(dts_Date.getCellData(1, "CALND_DD"));

    // 원화이자율스왑 (현재일-30 ~ 현재일)
    edt_FromDd5.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 30));
    edt_ToDd5.setValue($c.ut.cGetToday("yyyymmdd"));

    // 원화이자율스왑 (현재일-30 ~ 직전영업일)
    edt_FromDd6.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 30));
    edt_ToDd6.setValue(dts_Date.getCellData(1, "CALND_DD"));
};
